SELECT (
    SELECT DISTINCT salary
    FROM Employee
    ORDER BY salary DESC
    LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

CREATE FUNCTION getNthHighestSalary(N INT) RETURNS INT
BEGIN
  RETURN (
      SELECT DISTINCT salary
      FROM Employee
      ORDER BY salary DESC
      LIMIT 1 OFFSET N-1
  );
END;

SELECT
    score,
    DENSE_RANK() OVER (
        ORDER BY score DESC
    ) AS rank
FROM Scores;

WITH gaps AS (
    SELECT *,
           LAG(visit_date) OVER (
               PARTITION BY user_id
               ORDER BY visit_date
           ) AS prev_date
    FROM UserVisits
)
SELECT MAX(DATEDIFF(visit_date, prev_date)) AS max_gap
FROM gaps;

SELECT ROUND(
    (
        SELECT COUNT(*)
        FROM RequestAccepted
    ) /
    (
        SELECT COUNT(*)
        FROM FriendRequest
    ),
    2
) AS accept_rate;

SELECT tweet_id
FROM Tweets
WHERE CHAR_LENGTH(content) > 15;

SELECT candidate_id
FROM Candidates
WHERE skill IN ('Python', 'SQL');

SELECT
    DATE_FORMAT(day, '%d/%m/%Y') AS day
FROM Days;
